'use strict';
const { ApiError } = require('./errors');
const { fetchProbe } = require('./probe');
const { GUIDANCE } = require('./checks');

const NOTICES = [
  'Data source: PayPal Sandbox only. No Live account was used.',
  'Events marked "Verified by PayPal" were confirmed by PayPal\'s webhook signature verification API. Nothing else is labeled verified.',
  'Deliveries labeled duplicate, delayed or replay were generated by Faultline from stored genuine events. They are not new PayPal events and not new payments.',
  'Faultline sees your application\'s HTTP replies and, if you configured one, the state your own probe reports. It cannot see inside your application. Checks that need evidence it does not have are listed as "not evaluable" and are never counted as passes.',
  '"Passed" means at least one check on your application\'s own state held and none failed. "Inconclusive" means no such check could be evaluated.',
  'No AI was used to produce any verdict in this report.',
];
const VERDICT_LABEL = { passed: 'Passed', failed: 'Failed', inconclusive: 'Inconclusive' };
const mdCell = (v) => String(v ?? '').replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
const slug = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40) || 'project';

function registerReportRoutes({ app, db, forwarder, requireAuth, getProjectRow }) {
  const one = (sql, ...a) => db.prepare(sql).get(...a);
  const grouped = (sql, ...a) => Object.fromEntries(db.prepare(sql).all(...a).map((r) => [r.k ?? 'none', r.n]));

  app.get('/api/projects/:id/overview', requireAuth, (req, res) => {
    const p = getProjectRow(req.params.id);
    const recent = db.prepare(`SELECT r.id, r.kind, r.status, r.verdict, r.created_at, e.paypal_event_id FROM scenario_runs r JOIN webhook_events e ON e.id = r.event_id
      WHERE r.project_id = ? ORDER BY r.created_at DESC, r.rowid DESC LIMIT 5`).all(p.id)
      .map((r) => ({ id: r.id, label: forwarder.LABELS[r.kind], status: r.status, verdict: r.verdict, createdAt: r.created_at, paypalEventId: r.paypal_event_id }));
    res.json({
      orders: { total: one('SELECT COUNT(*) AS n FROM paypal_orders WHERE project_id = ?', p.id).n, byStatus: grouped('SELECT status AS k, COUNT(*) AS n FROM paypal_orders WHERE project_id = ? GROUP BY status', p.id) },
      captures: { total: one('SELECT COUNT(*) AS n FROM paypal_captures WHERE project_id = ?', p.id).n },
      events: { total: one('SELECT COUNT(*) AS n FROM webhook_events WHERE project_id = ?', p.id).n, byVerification: grouped('SELECT verification_status AS k, COUNT(*) AS n FROM webhook_events WHERE project_id = ? GROUP BY verification_status', p.id) },
      inboundDeliveries: { total: one('SELECT COUNT(*) AS n FROM webhook_deliveries WHERE project_id = ?', p.id).n, redeliveries: one('SELECT COUNT(*) AS n FROM webhook_deliveries WHERE project_id = ? AND is_redelivery = 1', p.id).n },
      forwardAttempts: { total: one('SELECT COUNT(*) AS n FROM forward_attempts WHERE project_id = ?', p.id).n, byOutcome: grouped('SELECT outcome AS k, COUNT(*) AS n FROM forward_attempts WHERE project_id = ? GROUP BY outcome', p.id) },
      runs: { total: one('SELECT COUNT(*) AS n FROM scenario_runs WHERE project_id = ?', p.id).n, byStatus: grouped('SELECT status AS k, COUNT(*) AS n FROM scenario_runs WHERE project_id = ? GROUP BY status', p.id), byVerdict: grouped('SELECT verdict AS k, COUNT(*) AS n FROM scenario_runs WHERE project_id = ? AND verdict IS NOT NULL GROUP BY verdict', p.id) },
      failedChecks: one("SELECT COUNT(*) AS n FROM assertion_results WHERE project_id = ? AND verdict = 'fail'", p.id).n,
      paypalCalls: one('SELECT COUNT(*) AS n FROM paypal_api_calls WHERE project_id = ?', p.id).n,
      probeConfigured: Boolean(p.probe_url),
      recentRuns: recent,
    });
  });

  function findings(projectId) {
    const rows = db.prepare(`SELECT check_id, MIN(name) AS name, MIN(category) AS category,
        SUM(verdict = 'fail') AS fail, SUM(verdict = 'pass') AS pass, SUM(verdict = 'not_evaluable') AS not_evaluable, COUNT(*) AS total,
        MAX(CASE WHEN verdict = 'fail' THEN evaluated_at END) AS last_failure_at,
        (SELECT run_id FROM assertion_results x WHERE x.project_id = a.project_id AND x.check_id = a.check_id AND x.verdict = 'fail' ORDER BY x.id DESC LIMIT 1) AS last_failed_run
      FROM assertion_results a WHERE project_id = ? AND verdict != 'not_applicable' GROUP BY check_id`).all(projectId);
    return rows
      .filter((r) => r.fail > 0 || (r.pass === 0 && r.not_evaluable > 0))
      .map((r) => ({
        checkId: r.check_id, name: r.name, category: r.category,
        kind: r.fail > 0 ? 'failing' : 'never_evaluated',
        failed: r.fail, passed: r.pass, notEvaluable: r.not_evaluable, runsEvaluated: r.total,
        lastFailureAt: r.last_failure_at, lastFailedRunId: r.last_failed_run,
        guidance: GUIDANCE[r.check_id] || null,
      }))
      .sort((a, b) => (a.kind === b.kind ? b.failed - a.failed : a.kind === 'failing' ? -1 : 1));
  }

  app.get('/api/projects/:id/findings', requireAuth, (req, res) => {
    res.json({ findings: findings(getProjectRow(req.params.id).id), guidanceNote: 'Guidance is general advice for this kind of failure. It is not generated from your code.' });
  });

  function collect(project, { verdict, runId }) {
    const where = ['r.project_id = ?'];
    const args = [project.id];
    if (runId) { where.push('r.id = ?'); args.push(runId); }
    if (verdict) { where.push('r.verdict = ?'); args.push(verdict); }
    const rows = db.prepare(`SELECT r.*, e.paypal_event_id, e.event_type, e.resource_id, e.verification_status, e.first_received_at, e.raw_body AS raw_body
      FROM scenario_runs r JOIN webhook_events e ON e.id = r.event_id WHERE ${where.join(' AND ')} ORDER BY r.created_at DESC, r.rowid DESC LIMIT 200`).all(...args);
    return rows.map((r) => {
      const attempts = db.prepare('SELECT * FROM forward_attempts WHERE run_id = ? ORDER BY attempt_no').all(r.id);
      const assertions = db.prepare('SELECT * FROM assertion_results WHERE run_id = ? ORDER BY id').all(r.id)
        .map((a) => ({ id: a.check_id, category: a.category, name: a.name, verdict: a.verdict, summary: a.summary, evidence: JSON.parse(a.evidence_json) }));
      return {
        run: { id: r.id, scenario: forwarder.LABELS[r.kind], kind: r.kind, triggeredBy: r.triggered_by, status: r.status, destination: r.destination_url, plannedAttempts: r.planned_attempts, params: JSON.parse(r.params_json), createdAt: r.created_at, startedAt: r.started_at, finishedAt: r.finished_at, errorText: r.error_text },
        event: { paypalEventId: r.paypal_event_id, eventType: r.event_type, resourceId: r.resource_id, verification: r.verification_status, receivedAt: r.first_received_at },
        verdict: r.verdict, verdictReason: r.verdict_reason, risks: r.risks_json ? JSON.parse(r.risks_json) : [],
        attempts: attempts.map((a) => ({ attempt: a.attempt_no, kind: a.delivery_kind, sentAt: a.sent_at, durationMs: a.duration_ms, outcome: a.outcome, httpStatus: a.http_status, error: a.error_text, reply: a.response_snippet, bodySha256: a.body_sha256 })),
        assertions,
        snapshots: forwarder.evidence.snapshotsFor(r.id),
      };
    });
  }

  function buildReport(project, filters) {
    const runs = collect(project, filters);
    const count = (v) => runs.filter((r) => r.verdict === v).length;
    return {
      reportVersion: 1,
      generatedAt: new Date().toISOString(),
      project: { id: project.id, name: project.name, environment: 'PayPal Sandbox', stateProbeConfigured: Boolean(project.probe_url) },
      notices: NOTICES,
      summary: { runs: runs.length, passed: count('passed'), failed: count('failed'), inconclusive: count('inconclusive'), noVerdict: runs.filter((r) => !r.verdict).length },
      findings: findings(project.id),
      runs,
    };
  }

  function toMarkdown(rep) {
    const L = [];
    L.push(`# Faultline test report: ${rep.project.name}`, '', `Generated ${rep.generatedAt}. Environment: ${rep.project.environment}. State probe configured: ${rep.project.stateProbeConfigured ? 'yes' : 'no'}.`, '');
    L.push('## How to read this report', '', ...rep.notices.map((n) => `- ${n}`), '');
    const s = rep.summary;
    L.push('## Summary', '', `Runs in this report: ${s.runs}. Passed: ${s.passed}. Failed: ${s.failed}. Inconclusive: ${s.inconclusive}. No verdict yet: ${s.noVerdict}.`, '');
    L.push('## Reliability findings', '');
    if (!rep.findings.length) L.push('No failing or never-evaluated checks.', '');
    for (const f of rep.findings) {
      L.push(`### ${f.name}`, '', f.kind === 'failing' ? `Failed in ${f.failed} of ${f.runsEvaluated} evaluated run(s).` : `Never evaluated (${f.notEvaluable} run(s) lacked the evidence it needs).`, '');
      if (f.guidance) L.push(`General guidance: ${f.guidance}`, '');
    }
    L.push('## Test runs', '');
    for (const r of rep.runs) {
      L.push(`### ${r.run.scenario} on ${r.event.eventType || 'event'} (${r.event.paypalEventId || 'no event ID'})`, '');
      L.push(`- Verdict: **${VERDICT_LABEL[r.verdict] || 'No verdict'}**${r.verdictReason ? `. ${r.verdictReason}` : ''}`);
      L.push(`- Run status: ${r.run.status}${r.run.errorText ? ` (${r.run.errorText})` : ''}. Started ${r.run.startedAt || 'n/a'}, finished ${r.run.finishedAt || 'n/a'}.`);
      L.push(`- Destination: ${r.run.destination}. Event verification: ${r.event.verification}. Received ${r.event.receivedAt}.`, '');
      if (r.attempts.length) {
        L.push('| Attempt | Kind | Sent at | Outcome | HTTP | Took (ms) | Reply or error |', '|---|---|---|---|---|---|---|');
        for (const a of r.attempts) L.push(`| ${a.attempt} | ${mdCell(a.kind)} | ${mdCell(a.sentAt)} | ${mdCell(a.outcome)} | ${a.httpStatus ?? ''} | ${a.durationMs} | ${mdCell((a.reply || a.error || '').slice(0, 120))} |`);
        L.push('');
      }
      if (r.assertions.length) {
        L.push('| Check | Category | Result | What was found |', '|---|---|---|---|');
        for (const a of r.assertions) L.push(`| ${mdCell(a.name)} | ${a.category} | ${a.verdict.replace('_', ' ')} | ${mdCell(a.summary)} |`);
        L.push('');
        for (const a of r.assertions.filter((x) => x.verdict === 'fail')) {
          L.push(`Evidence for failed check "${a.name}":`, ...a.evidence.map((e) => `- (${e.type}) ${e.text}`), '');
        }
      }
      if (r.risks.length) L.push('Inferred risks (suspicions, not verdicts):', ...r.risks.map((x) => `- ${x}`), '');
    }
    return L.join('\n');
  }

  app.get('/api/projects/:id/report', requireAuth, (req, res) => {
    const project = getProjectRow(req.params.id);
    const format = req.query.format === 'md' ? 'md' : req.query.format === 'json' || req.query.format === undefined ? 'json' : null;
    if (!format) throw new ApiError(400, 'validation_failed', 'Choose format json or md.');
    const verdict = typeof req.query.verdict === 'string' && VERDICT_LABEL[req.query.verdict] ? req.query.verdict : undefined;
    const runId = typeof req.query.runId === 'string' && req.query.runId ? req.query.runId : undefined;
    const rep = buildReport(project, { verdict, runId });
    const name = `faultline-report-${slug(project.name)}-${rep.generatedAt.slice(0, 10)}.${format}`;
    res.set('Content-Disposition', `attachment; filename="${name}"`);
    if (format === 'md') res.type('text/markdown').send(toMarkdown(rep));
    else res.type('application/json').send(JSON.stringify(rep, null, 2));
  });

  // Lets the developer check their probe before relying on it. Nothing is saved.
  app.post('/api/projects/:id/probe/test', requireAuth, async (req, res, next) => {
    try {
      const project = getProjectRow(req.params.id);
      if (!project.probe_url) throw new ApiError(400, 'probe_not_configured', 'Add a state probe URL to this project first.');
      let event = null;
      if (req.body && typeof req.body.eventId === 'string') event = db.prepare('SELECT * FROM webhook_events WHERE id = ? AND project_id = ?').get(req.body.eventId, project.id);
      const r = await fetchProbe({
        url: project.probe_url, eventId: event ? event.paypal_event_id : 'faultline-probe-test', resourceId: event ? event.resource_id : 'faultline-probe-test',
        eventType: event ? event.event_type : 'PAYMENT.CAPTURE.COMPLETED', timeoutMs: 10000,
      });
      res.json({ result: r, askedAbout: event ? 'a stored event' : 'a sample event ID (faultline-probe-test)' });
    } catch (err) { next(err); }
  });
}

module.exports = { registerReportRoutes, NOTICES };
